          ]
        },
        {
          "proposicao": "O PRE da unidade apresentava pontos de encontro e funções em diferentes locais da unidade, mas não apresentava a estrutura do Incident Command Team, isto é, quem deveria compor o time de comando do incidente.",
          "trechos": [
            "Ec059ea124b5760d7:0:698",
            "Ec059ea124b5760d7:698:1397"
